import 'dart:math';

List<double> findClosestElements(List<double> numbers) {
  int n = numbers.length;
  if (n <= 1) return List.from(numbers);

  double minDiff = double.infinity;
  int closestIndex = 0;

  for (int i = 0; i < n - 1; i++) {
    double diff = abs(numbers[i + 1] - numbers[i]);
    if (diff < minDiff) {
      minDiff = diff;
      closestIndex = i;
    }
  }

  // If all elements are the same, return the first element as the only one
  if (minDiff == 0.0) {
    return [numbers[0]];
  }

  // Find the index of the second smallest difference to determine the split point
  double secondMinDiff = double.infinity;
  int splitPoint = 0;

  for (int j = 0; j < n - 1; j++) {
    double currentDiff = abs(numbers[j + 1] - numbers[j]);

    if (currentDiff < secondMinDiff && currentDiff != minDiff) {
      secondMinDiff = currentDiff;
      splitPoint = j;
    }
  }

  // Handle cases where there's a tie in differences
  if (splitPoint > 0) {
    int leftLength = splitPoint + 1;
    int rightLength = n - splitPoint;

    if (leftLength < rightLength || (rightLength - leftLength) % 2 == 1) {
      return numbers.sublist(0, splitPoint + 1);
    } else {
      return numbers.sublist(splitPoint - 1, splitPoint + 1);
    }
  } else {
    return numbers.sublist(0, 2);
  }
}
