  int n = l.length;
  List<int> result = List<int>.filled(n, 0);
  int index = 0;
  for (int i = 0; i < n; i++) {
    bool isUnique = true;
    for (int j = 0; j < i; j++) {
      if (l[i] == l[j]) {
        isUnique = false;
        break;
      }
    }
    if (isUnique) {
      result[index++] = l[i];
    }
  }
  return result.sublist(0, index).toList();
}

