bool triplesSumToZero(List<int> l) {
  int n = l.length;
  if (n < 3) return false;

  l.sort();

  for (int i = 0; i < n - 2; ++i) {
    if (i > 0 && l[i] == l[i - 1]) continue;

    int left = i + 1;
    int right = n - 1;

    while (left < right) {
      final sum = l[i] + l[left] + l[right];

      if (sum == 0) {
        return true;
      } else if (sum < 0) {
        left++;
      } else {
        right--;
      }
    }
  }

  return false;
}
