  for (int j = 0; j < left.length; j++) {
    array[idx++] = left[j];
  }
  for (int k = 0; k < right.length; k++) {
    array[idx++] = right[k];
  }

  return array;
}

void swap(List<int> arr, int a, int b) {
  var temp = arr[a];
  arr[a] = arr[b];
  arr[b] = temp;
