List<int> sortArray(List<int> array) {
  final size = array.length;
  if (size <= 1) return array;

  int partition(int low, int high) {
    final pivotIndex = (low + high).toInt() ~/ 2;
    final pivotValue = array[pivotIndex];
    array[pivotIndex] = array[high];
    array[high] = pivotValue;

    var i = low;
    for (var j = low; j < high; j++) {
      if (array[j] <= pivotValue) {
        array[i] = array[j];
        array[j] = array[high];
        array[high] = array[i];
        i++;
      }
    }

    array[high] = array[i];
    array[i] = pivotValue;
    return i;
  }

  void quickSort(int low, int high) {
    if (low >= high) return;
    final pivotIndex = partition(low, high);
    quickSort(low, pivotIndex - 1);
    quickSort(pivotIndex + 1, high);
  }

  quickSort(0, size - 1);
  return array;
}
