    return lst[indices[a]] > lst[indices[b]];
  }

  void heapify(int root, int size) {
    int left = 2 * root + 1;
    while (left < size) {
      int smallest = root;
      if (isLess(left, smallest)) smallest = left;
      if (left + 1 < size && isLess(left + 1, smallest)) smallest = left + 1;
      if (smallest != root) {
        swap(root, smallest);
        root = smallest;
        left = 2 * root + 1;
      } else break;
    }
  }

  void buildHeap() {
