  var result = 0;

  for (var i = 0; i < rows; i++) {
    for (var j = 0; j < cols; j++) {
      if (!visited[i * cols + j] && grid[i][j] > 0) {
        final queue = Queue();
        queue.addLast(i * cols + j);
        visited[i * cols + j] = true;
        var fillAmount = 0;

        while (queue.isNotEmpty) {
          final cell = queue.removeFirst();
          final row = cell ~/ cols;
          final col = cell % cols;

