List<String> selectWords(String s, int n) {
  final List<String> result = [];
  final Queue<int> indices = Queue();

  void addIndices(int start, int end) {
    for (int i = start; i < end; i++) {
      if (s[i] == ' ') {
        indices.add(i);
      }
    }
  }

