  if (indices.isEmpty || n <= 0) {
    return result;
  }

  // Determine the starting index based on n-1-th element of indices
  int startIndex = indices.elementAt(n - 1) + 1;

  // Check if we have enough words to extract
  if (startIndex >= s.length) {
    return result;
  }

  // Extract the first word from startIndex onwards
  int endIndex = s.indexOf(' ', startIndex);
  String firstWord = endIndex != -1 ? s.substring(startIndex, endIndex) : s.substring(startIndex);

  result.add(firstWord);

  // If only one word was found, return it
  if (n == 1) {
    return result;
  }

  // Calculate the next set of indices excluding the current word's position
  int lastSpacePos = startIndex - 1;
  addIndices(lastSpacePos, s.length);

  // Get the remaining number of words to find
  int remainingWords = n - 1;

  // Process remaining words
