  final path = <int>[];
  int idx = rows * cols - 1;

  // Reconstruct the path by backtracking
  while (idx != 0) {
    path.add(grid[idx ~/ cols][idx % cols]);
    idx = (idx - grid[idx ~/ cols][idx % cols]) ~/ 2;
  }
  path.add(grid[0][0]);

  // Reverse to get the correct order
  path.reverse(); 
  return path;
}
