String fileNameCheck(String fileName) {
  if (fileName == null || fileName.isEmpty) return '';
  final dotIndex = fileName.lastIndexOf('.');
  if (dotIndex < 0) return '';

  final extension = fileName.substring(dotIndex + 1);
  if (extension.length > 3) return '';

  final allowedExtensions = ['txt', 'csv', 'log'];
  if (!allowedExtensions.contains(extension.toLowerCase())) return '';

  final namePart = fileName.substring(0, dotIndex);
  if (namePart.isEmpty) return '';

  // Check for invalid characters in the file name
  if (RegExp(r'[^a-zA-Z0-9_\-\.]').hasMatch(namePart)) return '';

  return fileName;
}
