import 'dart:io';

String fileNameCheck(String fileName) {
  if (fileName == null || fileName.isEmpty) return "Invalid file name";

  final invalidChars = {'<', '>', ':', '"', '/', '\\', '|', '?', '*'};
  for (var char in fileName.split('')) {
    if (invalidChars.contains(char)) {
      return "Invalid file name";
    }
  }

  // Check length constraints
  if (fileName.length < 1 || fileName.length > 255) {
    return "Invalid file name";
  }

  // Check reserved names on Windows
  const windowsReservedNames = {
    'CON', 'PRN', 'AUX', 'NUL',
    'COM1', 'COM2', 'COM3', 'COM4', 'COM5', 'COM6', 'COM7', 'COM8', 'COM9',
    'LPT1', 'LPT2', 'LPT3', 'LPT4', 'LPT5', 'LPT6', 'LPT7', 'LPT8', 'LPT9'
  };
  if (windowsReservedNames.containsKey(fileName.toUpperCase())) {
    return "Invalid file name";
  }

  // Check for volume label and trailing spaces
  if (fileName.startsWith(':\\') || fileName.endsWith(' ')) {
    return "Invalid file name";
  }

  return "Valid file name";
}
